mapper.select:
SELECT c.entry_id FROM memory_entry_coverage c

    JOIN memory_summaries s ON s.id = c.summary_id AND s.deleted = 0

WHERE c.tag_id = #{tagId} AND c.project_id = #{projectId}

    AND c.user_id = #{userId}
    AND c.user_id IS NULL


    AND s.direction IN (#{direction}, 'BOTH')

AND c.entry_id IN
#{eid}
